## Submitted testbench
```systemverilog
module tb;
  // -------------------------------------------------
  // Parameters and clock
  // -------------------------------------------------
  localparam int CLK_PERIOD = 8; // 125 MHz
  reg clk = 0;

  // -------------------------------------------------
  // DUT interface signals
  // -------------------------------------------------
  reg rst = 0;
  reg rxd = 1'b1;
  reg [15:0] prescale_input = 16'h0;

  reg [7:0] s_axis_tdata_int = 0;
  reg s_axis_tvalid_int = 0;

  // DUT output wires
  wire s_axis_tready_o;
  wire [7:0] m_axis_tdata;
  wire       m_axis_tvalid;
  wire       txd;
  wire       tx_busy;
  wire       rx_busy;
  wire       rx_overrun_error;
  wire       rx_frame_error;

  // Clock generation
  always #(CLK_PERIOD/2) clk = ~clk;

  // -------------------------------------------------
  // DUT instantiation
  // -------------------------------------------------
  uart #(.DATA_WIDTH(8)) dut (
    .clk               (clk),
    .rst               (rst),
    .s_axis_tdata      (s_axis_tdata_int),
    .s_axis_tvalid     (s_axis_tvalid_int),
    .s_axis_tready     (s_axis_tready_o),
    .m_axis_tdata      (m_axis_tdata),
    .m_axis_tvalid     (m_axis_tvalid),
    .m_axis_tready     (1'b1),           // always ready
    .rxd               (rxd),
    .txd               (txd),
    .tx_busy           (tx_busy),
    .rx_busy           (rx_busy),
    .rx_overrun_error  (rx_overrun_error),
    .rx_frame_error    (rx_frame_error),
    .prescale          (prescale_input)
  );

  // Use a moderately sized prescale to obtain a long busy window
  initial prescale_input = 16'd200;

  // -------------------------------------------------
  // Main stimulus
  // -------------------------------------------------
  initial begin
    // --- Reset ---
    rst = 1'b1;
    #(CLK_PERIOD*2);
    rst = 1'b0;
    #(CLK_PERIOD*2);

    // --- Wait for the AXI stream to be ready ---
    while (!s_axis_tready_o) @(posedge clk);

    // --- Load a dummy byte to make the transmitter become busy ---
    s_axis_tvalid_int <= 1'b1;
    s_axis_tdata_int  <= 8'hA5; // any payload
    @(posedge clk);
    s_axis_tvalid_int <= 1'b0;   // de‑assert after one cycle

    // --- Wait until tx_busy goes high (first frame is being transmitted) ---
    wait (tx_busy);

    // --- Advance so that bit_cnt is in the 1..8 range ---
    repeat (30) @(posedge clk);

    // --- Prepare the rising‑edge event that satisfies T11 ---
    // Keep valid low and load the target data word (8'h3C)
    s_axis_tvalid_int <= 1'b0;
    s_axis_tdata_int  <= 8'h3C;

    // On the next clock edge assert valid (rising edge) while busy is still high
    @(posedge clk);
    s_axis_tvalid_int <= 1'b1;   // rising edge observed by the coverage point

    // --- Hold long enough for the coverage counter to be hit ---
    repeat (20) @(posedge clk);

    // --- End simulation ---
    $finish;
  end
endmodule
```

